export function findWordById(wordId: string) {
  for (const chapter of vocabChapters) {
    const word = chapter.words.find((w) => w.id === wordId)
    if (word) return word
  }
  return undefined
}

export function allWords() {
  return vocabChapters.flatMap((c) => c.words)
}
